select s."SETTLEMENT_ID", s."PORTFOLIO_ID", p."PORTFOLIO_NO", p."PORTFOLIO_STATUS_CODE", d."DEVELOPER_CODE", d."LEGAL_NAME_AR" "DEVELOPER_NAME_AR", d."LEGAL_NAME_EN" "DEVELOPER_NAME_EN", pr."PROJECT_CODE", pr."PROJECT_NAME_AR", pr."PROJECT_NAME_EN", s."CONTRACT_EXECUTION_DATE", s."CUT_OFF_DATE", s."ACQUISITION_DATE", s."SETTLEMENT_DATE", s."ACCOUNTING_DATE", s."APPROVED_PURCHASE_VALUE", s."PAYMENT_AMOUNT", s."ACQUISITION_COST_AMOUNT", s."CURRENCY_CODE", s."PAYMENT_METHOD_CODE", pm."PAYMENT_METHOD_NAME_AR", pm."PAYMENT_METHOD_NAME_EN", s."BANK_GL_ACCOUNT_CODE", s."BANK_NAME", s."BANK_ACCOUNT_NO", s."TRANSFER_REFERENCE", s."CHEQUE_NO", s."CHEQUE_DATE", s."SELLER_PAYMENT_REFERENCE", s."SETTLEMENT_STATUS_CODE", s."ACCOUNTING_STATUS_CODE", s."GL_BATCH_REFERENCE", s."GL_JOURNAL_REFERENCE", s."NOTES", s."SETTLED_BY", s."SETTLED_ON_AT" AS "SETTLED_ON", s."CREATED_BY", s."CREATED_AT" AS "CREATED_ON", s."UPDATED_BY", s."UPDATED_AT" AS "UPDATED_ON"
from "MTG_PURCHASED_PORTFOLIO_SETTLEMENTS" s
join "MTG_PURCHASED_PORTFOLIOS" p on p."PORTFOLIO_ID" = s."PORTFOLIO_ID"
join "MTG_DEVELOPERS" d on d."DEVELOPER_ID" = p."DEVELOPER_ID"
join "MTG_PROJECTS" pr on pr."PROJECT_ID" = p."PROJECT_ID"
left join "MTG_LKP_PORTFOLIO_PAYMENT_METHODS" pm on pm."PAYMENT_METHOD_CODE" = s."PAYMENT_METHOD_CODE"
